function validate([satisfaction]) {
  if (satisfaction.length < 1 || satisfaction.length > 500) return 'satisfaction needs 1 to 500 values.';
  if (satisfaction.some(v => !Number.isInteger(v) || v < -1000 || v > 1000)) return 'Each value is an integer from -1000 to 1000.';
  return null;
}

