function maxSatisfaction(satisfaction) {
  satisfaction.sort((a, b) => b - a);
  let sum = 0;
  let total = 0;
  for (const value of satisfaction) {
    sum += value;
    if (sum <= 0) {
      break;
    }
    total += sum;
  }
  return total;
}

