function maxSatisfaction(satisfaction) {
  // A chosen set is best cooked from least to most liked, so sort ascending and decide dish by dish
  // whether to skip it or cook it next. best[j] is the largest total with exactly j dishes cooked so far.
  const dishes = [...satisfaction].sort((a, b) => a - b);
  const n = dishes.length;
  let best = [0, ...Array(n).fill(-Infinity)];
  for (const dish of dishes) {
    const next = best.slice();
    for (let j = 0; j < n; j++) {
      if (best[j] !== -Infinity) next[j + 1] = Math.max(next[j + 1], best[j] + (j + 1) * dish);
    }
    best = next;
  }
  return Math.max(...best);
}

