function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const n = size === 'large' ? 500 : 1 + pick(10);
  const span = size === 'large' || rand() < 0.3 ? 1000 : 10;
  // Shift the values so that some inputs are mostly negative and others mostly positive.
  const bias = Math.floor((rand() - 0.6) * span);
  const satisfaction = Array.from({ length: n }, () => Math.max(-1000, Math.min(1000, pick(2 * span + 1) - span + bias)));
  return [satisfaction];
}
